package com.nbi.profile.controller;

import com.nbi.profile.dto.*;
import com.nbi.profile.model.Beneficiary;
import com.nbi.profile.service.BeneficiaryService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;

@RestController
@RequestMapping("/api/v1/beneficiaries")
public class BeneficiaryController {

    private final BeneficiaryService service;
    public BeneficiaryController(BeneficiaryService service) { this.service = service; }

    @GetMapping("/{id}")
    public ResponseEntity<Beneficiary> get(@PathVariable String id) {
        return service.find(id).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    // PUT — full replace, validates ALL fields.
    @PutMapping("/{id}")
    public ResponseEntity<Beneficiary> put(@PathVariable String id,
                                           @Valid @RequestBody PutRequest r) {
        return ResponseEntity.ok(service.replace(id, r));
    }

    // PATCH — partial, validates only present fields.
    @PatchMapping("/{id}")
    public ResponseEntity<Beneficiary> patch(@PathVariable String id,
                                             @RequestBody PatchRequest r) {
        return service.patch(id, r).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }
}
```
